Method.Source:
/// <summary>
/// Gets the InventItemBarcode record for a specific Item and color
/// </summary>
/// <param name = "_itemId">ItemId</param>
/// <param name = "_colorName">EcoResColorName</param>
/// <param name = "_barcodeSetupId">BarcodeSetupId</param>
/// <param name = "_unitId">UnitOfMeasureSymbol</param>
/// <returns>InventItemBarcode</returns>
public static InventItemBarcode avaFindSalesBarcodeDimension_Color(ItemId _itemId, EcoResColorName _colorName, BarcodeSetupId _barcodeSetupId = '', UnitOfMeasureSymbol _unitId = '')
{
    InventDimCombination    avaInventDimCombination = InventTable::avaGetColorInventDimCombination(_itemId, _colorName);

    return InventItemBarcode::findSalesBarcodeDimension(_itemId, avaInventDimCombination.inventDim(), _barcodeSetupId, _unitId);
}
